use verus::prelude::*;

// Specification for concat:
//   - no special precondition (requires true)
//   - the result has length equal to the sum of the two input lengths
//   - the first a.len() elements of the result agree with a
//   - the next b.len() elements of the result agree with b
#[requires(true)]
#[ensures(result.len() == a.len() + b.len())]
#[ensures(forall(|i: usize| i < a.len() ==> result[i] == a[i]))]
#[ensures(forall(|j: usize| j < b.len() ==> result[a.len() + j] == b[j]))]
fn concat(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64> {
    // Pre-allocate enough space for both vectors
    let mut result = Vec::with_capacity(a.len() + b.len());
    // Extend with elements from the first vector
    result.extend_from_slice(a);
    // Extend with elements from the second vector
    result.extend_from_slice(b);
    result
}

